142	  /// Settings / About panels. Works in front-to-back z-order: forward surfaces the window just
143	  /// behind the front and sends the old front to the back; backward surfaces the backmost — so
144	  /// repeated presses rotate through *all* windows instead of bouncing between the front two.
145	  func cycleWindows(forward: Bool) {
146	    let cycleable = NSApp.orderedWindows.filter(isCycleableWindow)
147	    guard let plan = Self.cyclePlan(ordered: cycleable, forward: forward) else { return }
148	    plan.front.makeKeyAndOrderFront(nil)
