163	  /// Pure rotation math for `cycleWindows`, extracted so it's unit-testable without live z-ordering.
164	  /// `ordered` is the cycleable windows front-to-back. Returns the window to bring forward and, for
165	  /// the forward direction, the old front window to push to the back (so the rotation visits every
166	  /// window rather than ping-ponging between the front two). nil when there's nothing to cycle to.
167	  nonisolated static func cyclePlan<W>(ordered: [W], forward: Bool) -> (front: W, sendBack: W?)? {
168	    guard ordered.count > 1 else { return nil }
169	    return forward ? (ordered[1], ordered[0]) : (ordered[ordered.count - 1], nil)
