214	/// A forwarding `NSWindowDelegate` proxy that intercepts only `windowShouldClose:` so a window with a
215	/// live run command confirms and gracefully stops it before closing (issue #70, A3) — otherwise the
216	/// dev server is orphaned against a torn-down window (the per-window form of issue #7). Every other
217	/// delegate message forwards to SwiftUI's original delegate, so scene/restoration behaviour is intact.
218	final class WindowCloseGuard: NSObject, NSWindowDelegate {
219	  private weak var store: AppStore?
220	  private weak var forwarding: NSWindowDelegate?
221	
222	  init(store: AppStore, forwarding: NSWindowDelegate?) {
223	    self.store = store
224	    self.forwarding = forwarding
225	  }
226	
227	  func windowShouldClose(_ sender: NSWindow) -> Bool {
228	    MainActor.assumeIsolated {
229	      // During an app quit, `applicationShouldTerminate` already prompts + stops every window, so
230	      // don't prompt again here (de-dup, OV #10). No live run command → nothing to stop, close now.
231	      guard let store, !WindowRegistry.shared.isTerminating, store.hasLiveRunCommand else {
232	        return true
233	      }
234	      if Defaults[.confirmOnQuit] {
235	        let alert = NSAlert()
236	        alert.messageText = "Close this window?"
237	        alert.informativeText = "It has a running process. Closing the window will stop it."
238	        alert.addButton(withTitle: "Close")
239	        alert.addButton(withTitle: "Cancel")
240	        guard alert.runModal() == .alertFirstButtonReturn else { return false }
241	      }
242	      // Stop the run command(s), then close — return false now so the surfaces stay alive for the
243	      // graceful Ctrl-C + wait and are never freed mid-IO (the no-mass-free rule).
244	      store.gracefullyStopAllRunCommands(timeout: 5) { sender.close() }
245	      return false
246	    }
247	  }
